// LIFTOFF — a cartoon rocket that only knows one direction, and it's up.
// Drawn fighter: a plain ES module, no imports, everything from `api`.
//
//   STRIKE   (attack button)    the needle nose lunges. Forward, up or down; charged it headbutts with the whole cone.
//   GIMMICK  (special button)   BLAST OFF: hold to fly nose-first as a missile, the flame behind it burns. Costs FUEL.
//                               Held down: planted, a flamethrower straight down. Fuel refills on the ground.
//   RECOVERY (up + special)     LAUNCH: full thrust straight up, the fins steer, the column below burns.
//   GRAB     (grab button)      the fins pin them; the throw is a mini launch that flings them off the nose.
//
// Drawn geometry in fighter units: atk-fwd nose cone x 24..52 at y -43, flame x -32..-6;
// atk-up nose x 0, y -62..-86, flame y -34..0; atk-down nose x 1, y -30..-9.
export default function make(api) {
  const { hb, cap, key, mv, throwMove, spriteAnims, spriteLoops, B } = api;

  const stats = {
    weight: 82, walk: 2.8, run: 5.0, dashInit: 5.8, airSpeed: 3.6, airAccel: 0.18,
    fallSpeed: 7.2, fastFall: 11, gravity: 0.36, shortHop: 6.5, fullHop: 10.5, doubleJump: 8.5,
    jumps: 3, wallJump: false, traction: 0.45, height: 86, width: 34, crouchHeight: 56, landLag: 4, ledgeReach: 30,
  };

  const P = (extra) => ({ a: {}, ...extra });
  const rest = P({});
  const strikePoses = (total, hit, lean, hitPose = {}) => [
    key(0, P({ rot: -lean * 0.5, sx: 0.96, sy: 1.04 })),
    key(hit, P({ rot: lean, sx: 1.1, sy: 0.94, ...hitPose })),
    key(Math.min(total - 1, hit + 6), P({ rot: lean * 0.8, sx: 1.04, sy: 0.98 })),
    key(total, rest),
  ];
  const NOSE = { fx: 'tip' };
  const FLAME = { fx: 'energy' };

  // THE STRIKE: the needle nose lunges, 10 damage. `aim` points it: 'f' forward, 'b' behind, 'u' up, 'd' into the floor.
  const STRIKE = { total: 28, hit: 7, active: 4, damage: 10, r: 9 };
  const aim = (id, dir, opts = {}) => {
    const s = { ...STRIKE, ...opts };
    const start = dir === 'u' ? [0, -64] : dir === 'd' ? [2, -30] : dir === 'b' ? [-24, -43] : [24, -43];
    const end = dir === 'u' ? [0, -94] : dir === 'd' ? [2, -4] : dir === 'b' ? [-58, -43] : [58, -43];
    const angle = dir === 'u' ? 88 : dir === 'd' ? 75 : 40;
    const lean = dir === 'b' ? -3 : dir === 'f' ? 3 : 0;
    const hitPose = dir === 'u' ? { sx: 0.92, sy: 1.1 } : dir === 'd' ? { sx: 0.96, sy: 1.04 } : {};
    const cell = dir === 'u' ? 'atk-up' : dir === 'd' ? 'atk-down' : 'atk-fwd';
    return mv(id, s.total, [cap([s.hit, s.hit + s.active - 1], start[0], start[1], end[0], end[1], s.r, s.damage, s.angle ?? angle, s.base ?? 40, s.growth ?? 85, { ...NOSE, ...(s.hb ?? {}) })],
      strikePoses(s.total, s.hit, lean, hitPose), { cell, cellFlip: dir === 'b', ...(s.mv ?? {}) });
  };
  // GRAB: the fins pin them; every throw is the same short launch, flung off the nose the way you hold
  const GRAB = { total: 34, hit: 7, damage: 8 };
  const toss = (id, angle, base, growth, pose) => throwMove(id, 32, 14, GRAB.damage, angle, base, growth, [key(0, P({ sy: 0.9, sx: 1.06 })), key(14, P(pose)), key(32, rest)]);

  const moves = {
    // strike, forward
    jab1: aim('jab1', 'f', { total: 20, hit: 5, damage: 6, base: 30, growth: 40, mv: { iasa: 15 } }),
    ftilt: aim('ftilt', 'f'),
    dashAttack: aim('dashAttack', 'f', { total: 36, hit: 8, damage: 11, mv: { motion: [[1, 6, 0], [10, 3, 0], [18, 1, 0]] } }),
    nair: aim('nair', 'f', { total: 26, hit: 6, damage: 8, mv: { aerial: true, landingLag: 8 } }),
    fair: aim('fair', 'f', { mv: { aerial: true, landingLag: 11 } }),
    bair: aim('bair', 'b', { damage: 12, mv: { aerial: true, landingLag: 11 } }),
    // strike, up: the skyward stab
    utilt: aim('utilt', 'u', { damage: 9 }),
    uair: aim('uair', 'u', { damage: 9, mv: { aerial: true, landingLag: 9 } }),
    // strike, down: tipped over, spearing the floor; dair spikes
    dtilt: aim('dtilt', 'd', { damage: 8 }),
    dair: aim('dair', 'd', { total: 38, hit: 12, damage: 12, angle: 270, base: 30, growth: 70, hb: { spike: true }, mv: { aerial: true, landingLag: 15, hover: [8, 12] } }),
    // charged: rears back and headbutts with the full cone, the needle tip is the sweetspot
    fsmash: mv('fsmash', 50, [
      hb([15, 17], 62, -43, 8, 20, 38, 45, 100, { ...NOSE, priority: 0 }),
      cap([15, 19], 30, -43, 58, -43, 11, 17, 40, 42, 95, { fx: 'heavy', priority: 1 }),
    ], [key(0, P({ dx: -8, sx: 0.92, sy: 1.04, rot: -4 })), key(15, P({ dx: 4, sx: 1.1, sy: 0.94, rot: 3 })), key(22, P({ dx: 2, sx: 1.04 })), key(50, rest)], { smash: true }),
    usmash: aim('usmash', 'u', { total: 48, hit: 14, active: 6, damage: 17, base: 42, growth: 100, mv: { smash: true } }),
    dsmash: mv('dsmash', 52, [
      cap([16, 20], -16, -6, 16, -6, 11, 15, 32, 42, 92, { fx: 'heavy' }),
    ], [key(0, P({ dy: -8, sy: 1.05 })), key(16, P({ sx: 1.12, sy: 0.9 })), key(24, P({ sx: 1.04, sy: 0.97 })), key(52, rest)], { smash: true, cell: 'atk-down' }),
    // grab
    grab: mv('grab', GRAB.total, [hb([GRAB.hit, GRAB.hit + 2], 22, -40, 14, 0, 0, 0, 0, { grab: true })], strikePoses(GRAB.total, GRAB.hit, 8), { isGrab: true, cell: 'idle' }),
    dashGrab: mv('dashGrab', 40, [hb([9, 11], 28, -40, 15, 0, 0, 0, 0, { grab: true })], strikePoses(40, 9, 14), { isGrab: true, cell: 'idle', motion: [[1, 5, 0], [9, 0, 0]] }),
    pummel: mv('pummel', 16, [], [key(0, P({ sx: 1.04 })), key(6, P({ sx: 0.92, sy: 1.06 })), key(16, P({ sx: 1.04 }))], { cell: 'idle' }),
    fthrow: toss('fthrow', 45, 60, 72, { rot: 30, sx: 1.1, dy: -10 }),
    bthrow: toss('bthrow', 40, 65, 80, { rot: -40, dy: -10 }),
    uthrow: toss('uthrow', 90, 70, 92, { dy: -24, sy: 1.14, sx: 0.92 }),
    dthrow: toss('dthrow', 68, 45, 42, { sy: 0.8, sx: 1.15, dy: 10 }),
    // GIMMICK, BLAST OFF: nose-first missile, held to keep burning; the flame trail behind multi-hits
    nspecial: mv('nspecial', 60, [
      cap([8, 40], 24, -43, 60, -43, 10, 11, 38, 50, 88, { fx: 'heavy', group: 0 }),
      cap([8, 40], -34, -44, -6, -44, 11, 3, 45, 25, 30, { ...FLAME, rehit: 8, group: 1 }),
    ], [key(0, P({ dx: -4, sx: 0.9, sy: 1.06 })), key(8, P({ sx: 1.12, sy: 0.94 })), key(40, P({ sx: 1.08, sy: 0.96 })), key(44, P({ rot: -10, sx: 0.96 })), key(60, rest)], { hook: 'missile', cell: 'atk-fwd' }),
    sspecial: mv('sspecial', 60, [
      cap([8, 40], 24, -43, 60, -43, 10, 11, 38, 50, 88, { fx: 'heavy', group: 0 }),
      cap([8, 40], -34, -44, -6, -44, 11, 3, 45, 25, 30, { ...FLAME, rehit: 8, group: 1 }),
    ], [key(0, P({ dx: -4, sx: 0.9, sy: 1.06 })), key(8, P({ sx: 1.12, sy: 0.94 })), key(40, P({ sx: 1.08, sy: 0.96 })), key(44, P({ rot: -10, sx: 0.96 })), key(60, rest)], { hook: 'missile', cell: 'atk-fwd' }),
    // the gimmick held down: planted flamethrower straight down, a slow hover in the air
    dspecial: mv('dspecial', 50, [
      cap([7, 36], -16, -4, 16, -4, 10, 2, 60, 30, 20, { ...FLAME, rehit: 5, group: 0 }),
      cap([7, 36], 0, -30, 0, -6, 9, 2, 60, 30, 20, { ...FLAME, rehit: 5, group: 0 }),
    ], [key(0, P({ sx: 1.08, sy: 0.9 })), key(7, P({ sx: 0.94, sy: 1.08 })), key(36, P({ sx: 0.96, sy: 1.06 })), key(50, rest)], { hook: 'jet', cell: 'atk-up' }),
    // RECOVERY, LAUNCH: straight up nose-first, the column beneath burns and drags down
    uspecial: mv('uspecial', 56, [
      cap([5, 12], 0, -66, 0, -94, 10, 8, 85, 50, 70, { ...NOSE, group: 0 }),
      cap([5, 34], 0, -32, 0, 4, 10, 2, 270, 25, 20, { ...FLAME, rehit: 6, group: 1 }),
    ], [key(0, P({ sx: 1.1, sy: 0.86 })), key(5, P({ sx: 0.9, sy: 1.14 })), key(40, P({ sy: 1.04 })), key(56, rest)], { hook: 'launch', helpless: true, ledgeOk: true, cell: 'atk-up' }),
    ledgeAttack: aim('ledgeAttack', 'f', { total: 38, hit: 12, damage: 9 }),
    getupAttack: aim('getupAttack', 'f', { total: 40, hit: 12, damage: 7 }),
    taunt: mv('taunt', 50, [], [key(0, rest), key(12, P({ dy: -10, sy: 1.08, sx: 0.94 })), key(26, P({ dy: -4, rot: 6 })), key(38, P({ dy: -10, rot: -6 })), key(50, rest)], { cell: 'idle' }),
  };

  const endFlight = (f, bonk) => {
    f.frame = 40;
    if (bonk) { f.vx = -f.moveFacing * 3; f.vy = -3; }
  };

  return {
    id: 'liftoff', // replaced by the forge with the player's fighter id
    name: 'LIFTOFF',
    tagline: 'Only knows one direction and it\u2019s up.',
    stats,
    moves,
    rig: { bones: [], anims: spriteAnims(), loops: spriteLoops },
    palette: { colors: { marker: '#d9402b' }, accent: 'marker', outline: '#1c1c1c' },
    // every key must exist from the start: the state hash walks these
    special: () => ({ fuel: 100, burn: 0, lastX: 0, bonk: 0 }),
    hooks: {
      missile: ({ state, f, input }) => {
        const s = f.special;
        if (f.frame === 1) {
          s.burn = 0; s.bonk = 0;
          // too little fuel to light: a sputter and nothing else
          if (s.fuel < 12) { f.frame = 44; return; }
        }
        if (f.frame < 8) { f.vx *= 0.8; if (!f.grounded) f.vy = Math.min(f.vy, 0.5); return; }
        if (f.frame > 40) { f.vx *= 0.9; return; }
        if (f.frame === 8) { s.fuel = Math.max(0, s.fuel - 10); f.grounded = false; f.platform = -1; }
        else if (Math.abs(f.x - s.lastX) < 2) { endFlight(f, true); return; }
        // the nose connected last frame: bonk off them
        if (s.bonk > 0 && --s.bonk === 0) { endFlight(f, true); return; }
        const nx = f.x + f.moveFacing * 52, ny = f.y - 43;
        for (const o of state.fighters) {
          if (o !== f && s.bonk === 0 && Math.abs(o.x - nx) < 20 && ny > o.y - 86 && ny < o.y + 4) s.bonk = 2;
        }
        s.lastX = f.x;
        f.vx = f.moveFacing * 8;
        f.vy = -0.35;
        s.fuel = Math.max(0, s.fuel - 1.4);
        s.burn++;
        if (f.frame >= 20 && (!(input.b & B.SPECIAL) || s.fuel <= 0)) { endFlight(f, false); return; }
        if (f.frame === 40 && s.burn < 60) f.frame = 39;
      },
      jet: ({ f, input }) => {
        const s = f.special;
        if (f.frame === 1) {
          s.burn = 0;
          if (s.fuel < 8) { f.frame = 40; return; }
        }
        if (f.frame < 7 || f.frame > 36) return;
        if (!f.grounded) f.vy = Math.min(f.vy, 0.6);
        f.vx *= 0.9;
        s.fuel = Math.max(0, s.fuel - 2.2);
        s.burn++;
        if (f.frame >= 16 && (!(input.b & B.SPECIAL) || s.fuel <= 0)) { f.frame = 36; return; }
        if (f.frame === 36 && s.burn < 60) f.frame = 35;
      },
      launch: ({ f, input }) => {
        const s = f.special;
        if (f.frame < 5) { f.vy = Math.min(f.vy, 0); return; }
        if (f.frame === 5) { f.grounded = false; f.platform = -1; f.usedUpSpecial = true; s.fuel = Math.max(0, s.fuel - 30); }
        if (f.frame <= 40) {
          f.vy = -10 + (f.frame - 5) * 0.2;
          f.vx = (input.x / 100) * 5.5;
        }
      },
    },
    onFrame: ({ f }) => { if (f.grounded && f.special.fuel < 100) f.special.fuel = Math.min(100, f.special.fuel + 1.2); },
    meters: [{ label: 'FUEL', color: '#e8452c', get: (f) => f.special.fuel / 100 }],
    visual: (f) => ({ glow: (100 - f.special.fuel) / 100 * 0.6 }),
  };
}
